CREATE TABLE IF NOT EXISTS visits(id TEXT PRIMARY KEY,opened TEXT,last_seen TEXT,seconds INTEGER DEFAULT 0,device TEXT,country TEXT,referrer TEXT,identity TEXT,generated INTEGER DEFAULT 0,export_click INTEGER DEFAULT 0,exported INTEGER DEFAULT 0,email_click INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,owner TEXT,body TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS usage(day TEXT PRIMARY KEY,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS oauth(state TEXT PRIMARY KEY,report_id TEXT,owner TEXT,created TEXT);

CREATE TABLE IF NOT EXISTS preferences(report_id TEXT PRIMARY KEY,opt_in INTEGER NOT NULL,name TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deliveries(report_id TEXT PRIMARY KEY,email TEXT NOT NULL,created TEXT NOT NULL,status TEXT NOT NULL,document_id TEXT);
